typedef unsigned int uint32;

class KSReplay { public: void Pause(bool paused); };
extern KSReplay ksreplay;
__asm__(".equ ksreplay, 0x004252A8");
__asm__(".equ Pause__8KSReplayb, 0x0023C9E0");

class IGOFrontEnd {
    char data[1492];
    bool replay_mode;
public:
    void ShowMenuBackground(bool on = true);
    void SetDisplay(bool display);
    void OnReplayEnd() { ShowMenuBackground(true); replay_mode = false; }
};
__asm__(".equ ShowMenuBackground__11IGOFrontEndb, 0x0017CED0");
__asm__(".equ SetDisplay__11IGOFrontEndb, 0x0017B9A8");

struct PauseMenuSystem;
struct FEManager { IGOFrontEnd *IGO; PauseMenuSystem *pms; };
struct PauseMenuSystem {
    char data[144];
    bool draw;
    bool replay_mode;
    bool end_level;
    char padding;
    FEManager *manager;
};

class Track { char data[72]; public: void Pause(); };
class MusicListing {
    int totalSources;
    int current;
    Track sources[50];
    uint32 currentSoundId;
    bool successfulLastPlay;
public:
    int order[50];
    bool enabled[50];
    void pause() { sources[order[current]].Pause(); }
};
class MusicMan {
    void *vtable;
    float volume;
    int inited;
    bool paused;
public:
    static MusicMan *instance;
    static MusicMan *inst() { return instance; }
    MusicListing musicTrack;
    void stop();
    void pause() { if (!paused) { paused = true; musicTrack.pause(); } }
};
__asm__(".equ _8MusicMan$instance, 0x00427B18");
__asm__(".equ stop__8MusicMan, 0x002595F0");
__asm__(".equ Pause__5Track, 0x002586E8");

class os_developer_options {
    void *vtable;
public:
    enum flags_t { FLAG_NO_AUDIO = 17 };
    static os_developer_options *instance;
    static os_developer_options *inst() { return instance; }
private:
    bool flags[80];
public:
    bool is_flagged(flags_t flag) const { return flags[flag]; }
};
__asm__(".equ _20os_developer_options$instance, 0x0045B180");

struct ReplayMenuVTable {
    char padding[192];
    short triangle_adjustment;
    short reserved;
    void (*triangle)(void *, int);
};
class ReplayMenuClass {
    char data[116];
    ReplayMenuVTable *vtable;
    PauseMenuSystem *sys;
public:
    void ReplayEnd();
    virtual void OnTriangle(int controller);
};

void ReplayMenuClass::ReplayEnd()
{
    ksreplay.Pause(true);
    sys->replay_mode = false;
    sys->draw = true;
    sys->manager->IGO->SetDisplay(false);
    sys->manager->IGO->OnReplayEnd();
    sys->manager->pms->replay_mode = false;

    if (!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
    {
        MusicMan::inst()->stop();
        MusicMan::inst()->pause();
    }

    OnTriangle(0);
}
